head.b:skin:
/* ================================
   GSM HASAN PREMIUM BLOGGER THEME
   ================================ */

*{
  box-sizing:border-box;
}

html{
  scroll-behavior:smooth;
}
body{
  margin:0;
  padding:0;
  background:#070b14;
  color:#e8eef7;
  font-family:Arial,Helvetica,sans-serif;
  line-height:1.7;
}

a{
  color:#42a5ff;
  text-decoration:none;
}

a:hover{
  color:#00e5ff;
}

/* HEADER */

.gh-header{
  background:linear-gradient(135deg,#05070d,#0b1730,#06111e);
  border-bottom:1px solid rgba(0,200,255,.25);
  box-shadow:0 5px 30px rgba(0,0,0,.5);
  position:relative;
  z-index:999;
}

.gh-top{
  max-width:1200px;
  margin:auto;
  padding:22px 18px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
}

.gh-logo{
  font-size:28px;
  font-weight:900;
  letter-spacing:2px;
  color:#fff;
}

.gh-logo span{
  color:#00d9ff;
}

.gh-tag{
  font-size:12px;
  color:#9db0c8;
  margin-top:3px;
}

.gh-wa{
  background:#16c76a;
  color:#fff!important;
  padding:11px 18px;
  border-radius:30px;
  font-weight:bold;
  box-shadow:0 5px 20px rgba(22,199,106,.25);
}

/* NAVIGATION */

.gh-nav{
  background:#090f1b;
  border-top:1px solid rgba(255,255,255,.05);
}

.gh-nav-inner{
  max-width:1200px;
  margin:auto;
  display:flex;
  overflow-x:auto;
  white-space:nowrap;
}

.gh-nav a{
  display:block;
  padding:14px 17px;
  color:#d8e4f2;
  font-size:14px;
  font-weight:bold;
}

.gh-nav a:hover{
  background:#0e233b;
  color:#00e5ff;
}

/* HERO */

.gh-hero{
  max-width:1200px;
  margin:25px auto;
  padding:42px 25px;
  border-radius:22px;
  background:
    radial-gradient(circle at 80% 20%,rgba(0,229,255,.18),transparent 35%),
    linear-gradient(135deg,#0c1729,#07101d);
  border:1px solid rgba(0,210,255,.2);
  text-align:center;
  box-shadow:0 20px 60px rgba(0,0,0,.35);
}

.gh-hero h1{
  margin:0;
  font-size:42px;
  color:#fff;
  letter-spacing:2px;
}

.gh-hero h1 span{
  color:#00dcff;
}

.gh-hero p{
  color:#aabbd0;
  margin:12px 0 25px;
}

.gh-btn{
  display:inline-block;
  padding:12px 22px;
  border-radius:30px;
  background:linear-gradient(90deg,#008cff,#00d9ff);
  color:#fff!important;
  font-weight:bold;
  margin:5px;
  box-shadow:0 8px 25px rgba(0,170,255,.25);
}

/* CATEGORY BOXES */

.gh-categories{
  max-width:1200px;
  margin:25px auto;
  padding:0 15px;
  display:grid;
  grid-template-columns:repeat(5,1fr);
  gap:12px;
}

.gh-cat{
  background:#0d1523;
  border:1px solid #182b42;
  padding:17px 10px;
  text-align:center;
  border-radius:14px;
  color:#dce9f7;
  font-weight:bold;
  transition:.25s;
}

.gh-cat:hover{
  transform:translateY(-3px);
  border-color:#00cfff;
  box-shadow:0 10px 30px rgba(0,180,255,.12);
}

.gh-categories a[href='/search/label/FRP'],
.gh-categories a[href='/search/label/FLASHING'],
.gh-categories a[href='/search/label/TOOLS'],
.gh-categories a[href='/search/label/DRIVERS'],
.gh-categories a[href='/search/label/EDL']{
  display:none!important;
}
}
}

/* MAIN */

.gh-container{
  max-width:1200px;
  margin:30px auto;
  padding:0 15px;
  display:grid;
  grid-template-columns:minmax(0,1fr) 320px;
  gap:25px;
}

.gh-main,
.gh-sidebar{
  min-width:0;
}

/* WIDGETS */

.widget{
  background:#0c1421;
  border:1px solid #182b42;
  border-radius:16px;
  padding:18px;
  margin-bottom:20px;
  box-shadow:0 10px 35px rgba(0,0,0,.18);
}

.widget h2,
.widget h3,
.widget .title{
  color:#fff;
  margin-top:0;
}

/* BLOG POSTS */

.blog-posts .post-outer{
  background:#0c1421;
  border:1px solid #182b42;
  border-radius:18px;
  padding:22px;
  margin-bottom:20px;
  box-shadow:0 10px 35px rgba(0,0,0,.2);
}

.post-title,
.post-title a{
  color:#fff!important;
  font-size:26px;
  line-height:1.3;
  font-weight:800;
}

.post-title a:hover{
  color:#00d9ff!important;
}

.post-body{
  color:#c4d0df;
  font-size:16px;
}

.post-body img{
  max-width:100%;
  height:auto;
  border-radius:12px;
}

.post-header,
.post-footer{
  color:#8093aa;
  font-size:13px;
}

/* SIDEBAR */

.gh-sidebar .widget a{
  display:block;
  padding:7px 0;
  border-bottom:1px solid rgba(255,255,255,.05);
}

/* SEARCH */

.gh-search{
  display:flex;
  margin-bottom:20px;
}

.gh-search input{
  flex:1;
  background:#0d1726;
  color:#fff;
  border:1px solid #203650;
  padding:12px 15px;
  border-radius:12px 0 0 12px;
  outline:none;
}

.gh-search button{
  border:0;
  padding:0 18px;
  border-radius:0 12px 12px 0;
  background:#009dff;
  color:#fff;
  font-weight:bold;
}

/* FOOTER */

.gh-footer{
  margin-top:50px;
  background:#050911;
  border-top:1px solid #17263a;
  padding:35px 15px;
}

.gh-footer-inner{
  max-width:1200px;
  margin:auto;
  text-align:center;
}

.gh-footer-title{
  font-size:23px;
  font-weight:bold;
  color:#fff;
}

.gh-footer-title span{
  color:#00d9ff;
}

.gh-footer p{
  color:#7f91a7;
  font-size:13px;
}

/* FLOATING WHATSAPP */

..gh-floating-wa,
a[aria-label="WhatsApp"],
a[href*="wa.me"] {
    display: none !important;
    visibility: hidden !important;
    opacity: 0 !important;
    pointer-events: none !important;
}

/* BACK TOP */

#ghTop{
  position:fixed;
  right:18px;
  bottom:85px;
  width:42px;
  height:42px;
  border:0;
  border-radius:50%;
  background:#008cff;
  color:#fff;
  cursor:pointer;
  display:none;
  z-index:9998;
}

/* MOBILE */

@media(max-width:800px){

  .gh-top{
    padding:17px 13px;
  }

  .gh-logo{
    font-size:21px;
  }

  .gh-tag{
    font-size:10px;
  }

  .gh-wa{
    padding:9px 12px;
    font-size:12px;
  }

  .gh-hero{
    margin:15px 10px;
    padding:30px 15px;
  }

  .gh-hero h1{
    font-size:30px;
  }

  .gh-categories{
    grid-template-columns:repeat(2,1fr);
    padding:0 10px;
  }

  .gh-container{
    display:block;
    margin-top:20px;
  }

  .gh-sidebar{
    margin-top:25px;
  }

  .post-title,
  .post-title a{
    font-size:22px;
  }

}

/* VERY SMALL */

@media(max-width:400px){

  .gh-categories{
    grid-template-columns:1fr 1fr;
  }

  .gh-hero h1{
    font-size:26px;
  }

}
.gh-logo {
  font-size: 55px;
  font-weight: 900;
  text-align: center;
  letter-spacing: 3px;
  text-transform: uppercase;

  background: linear-gradient(
    90deg,
    #00c6ff,
    #00ff88,
    #fff200,
    #ff4d4d,
    #d500ff,
    #00c6ff
  );

  background-size: 400% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;

  animation: ghColor 5s linear infinite;
}

@keyframes ghColor {
  0% {
    background-position: 0% center;
  }

  100% {
    background-position: 400% center;
  }
}.gh-logo {
  font-size: 55px;
  font-weight: 900;
  text-align: center;
  letter-spacing: 3px;
  text-transform: uppercase;

  white-space: nowrap;
  width: 100%;
  box-sizing: border-box;

  background: linear-gradient(
    90deg,
    #00c6ff,
    #00ff88,
    #fff200,
    #ff4d4d,
    #d500ff,
    #00c6ff
  );

  background-size: 400% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;

  animation: ghColor 5s linear infinite;
}

@keyframes ghColor {
  0% {
    background-position: 0% center;
  }

  100% {
    background-position: 400% center;
  }
}

/* MOBILE */
@media (max-width:600px) {
  .gh-logo {
    font-size: 27px;
    letter-spacing: 1px;
    white-space: nowrap;
  }
}/* GSM HASAN - PREMIUM SOFTWARE CARDS */
.gh-categories {
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px !important;
  padding: 12px !important;
}

.gh-categories > a {
  box-sizing: border-box;
  min-width: 0;
  padding: 20px 12px !important;
  border: 1px solid rgba(0, 195, 255, 0.30) !important;
  border-radius: 16px !important;
  background: linear-gradient(145deg, #101e3b, #080f20) !important;
  color: #eaf7ff !important;
  text-align: center !important;
  font-weight: 700 !important;
  text-decoration: none !important;
  box-shadow: 0 5px 18px rgba(0, 0, 0, 0.22),
              inset 0 1px 0 rgba(255, 255, 255, 0.04);
  transition: border-color 0.25s ease,
              box-shadow 0.25s ease,
              transform 0.25s ease;
}

.gh-categories > a:hover {
  border-color: #00d9ff !important;
  box-shadow: 0 0 18px rgba(0, 217, 255, 0.24);
  transform: translateY(-4px);
}

@media (max-width: 768px) {
  .gh-categories {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px !important;
    padding: 8px !important;
  }

  .gh-categories > a {
    padding: 16px 8px !important;
    border-radius: 13px !important;
    font-size: 13px !important;
    overflow-wrap: anywhere;
  }
}

@media (min-width: 769px) and (max-width: 1000px) {
  .gh-categories {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}/* GSM HASAN PREMIUM UPGRADE */

.gh-categories > a {
  background: linear-gradient(145deg,#101d38,#071020) !important;
  border: 1px solid rgba(0,180,255,.35) !important;
  border-radius: 18px !important;
  padding: 25px 15px !important;
  box-shadow: 0 5px 20px rgba(0,120,255,.12) !important;
  transition: all .35s ease !important;
  color: #fff !important;
}

.gh-categories > a:hover {
  transform: translateY(-7px) !important;
  border-color: #00d9ff !important;
  box-shadow: 0 10px 30px rgba(0,180,255,.35) !important;
  background: linear-gradient(135deg,#102c55,#071020) !important;
}

.gh-logo {
  text-shadow: 0 0 15px rgba(0,180,255,.6);
  letter-spacing: 2px;
}

a[href*="wa.me"],
a[href*="whatsapp.com/channel"],
a[href*="youtube.com"],
a[href*="t.me"] {
  transition: .3s ease !important;
}

a[href*="wa.me"]:hover,
a[href*="whatsapp.com/channel"]:hover,
a[href*="youtube.com"]:hover,
a[href*="t.me"]:hover {
  filter: brightness(1.2);
  transform: translateY(-3px);
}/* ===== GSM HASAN ONLINE COURSE PREMIUM BOX ===== */

.gh-course-box {
  max-width: 650px;
  margin: 28px auto;
  padding: 25px;
  text-align: center;
  color: #fff;
  background: linear-gradient(145deg,#101f3d,#030812);
  border: 1px solid #078cff;
  border-radius: 20px;
  box-shadow: 0 10px 35px rgba(0,140,255,.25);
}

.gh-admission {
  display: inline-block;
  background: #073c2a;
  color: #38ffae;
  padding: 9px 16px;
  border-radius: 30px;
  font-size: 12px;
  font-weight: bold;
}

.gh-course-box h2 {
  color: #00d9ff;
  font-size: 30px;
  margin: 18px 0 5px;
  font-weight: 900;
}

.gh-course-box h3 {
  color: #fff;
  font-size: 19px;
}

.gh-course-box p {
  color: #9bc8ed;
  line-height: 1.7;
}

.gh-course-price {
  color: #00e5ff;
  font-size: 36px;
  font-weight: 900;
  margin: 20px 0;
}

.gh-course-price small {
  font-size: 14px;
}

.gh-course-box h4 {
  color: #00d9ff;
  text-align: left;
}

.gh-course-box ul {
  text-align: left;
  line-height: 2.1;
  color: #d9eaff;
  padding-left: 25px;
}

.gh-course-details {
  background: #102b4c;
  border: 1px solid #087cff;
  border-radius: 12px;
  padding: 15px;
  line-height: 2;
  margin: 20px 0;
  color: #fff;
}

.gh-course-box > a {
  display: block;
  padding: 15px;
  background: linear-gradient(90deg,#006dff,#00d9ff);
  color: white !important;
  font-weight: 900;
  border-radius: 12px;
  text-decoration: none;
}

.gh-course-box > a:hover {
  box-shadow: 0 0 20px #008cff;
  transform: translateY(-3px);
}

.gh-course-box > small {
  display: block;
  color: #00d9ff;
  margin-top: 20px;
  font-weight: bold;
}

@media(max-width:600px) {
  .gh-course-box {
    margin: 18px 10px;
    padding: 18px;
  }
}/* ===== GSM HASAN PREMIUM CATEGORY CSS ===== */

.gh-categories {
  background: linear-gradient(135deg,#020b19,#092344,#031326) !important;
  border: 1px solid #078bdb !important;
  border-radius: 20px !important;
  padding: 22px 14px !important;
  box-shadow: 0 0 25px rgba(0,150,255,.2) !important;
}

.gh-categories h2 {
  color: #20dcff !important;
  text-shadow: 0 0 15px #008cff;
  font-weight: 900 !important;
  letter-spacing: 2px;
}

.gh-categories p {
  color: #d5eaff !important;
}

.gh-categories > div[style*="display:grid"] {
  display: grid !important;
  grid-template-columns: repeat(5,minmax(0,1fr)) !important;
  gap: 13px !important;
}

.gh-categories > div[style*="background:#0c2948"] {
  background: linear-gradient(155deg,#123c69,#06162c) !important;
  border: 1px solid #078bda !important;
  border-radius: 17px !important;
  padding: 17px 12px !important;
  box-shadow: inset 0 0 18px rgba(0,170,255,.12),
              0 5px 18px rgba(0,0,0,.4) !important;
  transition: all .3s ease !important;
}

.gh-categories > div[style*="background:#0c2948"]:hover {
  transform: translateY(-6px);
  border-color: #00e5ff !important;
  box-shadow: 0 0 22px rgba(0,200,255,.4) !important;
}

.gh-categories h3 {
  color: #20dcff !important;
  font-weight: 800 !important;
  font-size: 15px !important;
}

.gh-categories a {
  color: #d9edff !important;
  text-decoration: none !important;
  font-size: 13px !important;
  transition: .2s;
}

.gh-categories a:hover {
  color: #00eaff !important;
  padding-left: 5px;
}

@media(max-width:1000px) {
  .gh-categories > div[style*="display:grid"] {
    grid-template-columns: repeat(3,minmax(0,1fr)) !important;
  }
}

@media(max-width:600px) {
  .gh-categories {
    padding: 14px 8px !important;
  }
  .gh-categories > div[style*="display:grid"] {
    grid-template-columns: repeat(2,minmax(0,1fr)) !important;
    gap: 9px !important;
  }
  .gh-categories > div[style*="background:#0c2948"] {
    padding: 12px 8px !important;
  }
  .gh-categories h3 {
    font-size: 12px !important;
  }
  .gh-categories a {
    font-size: 11px !important;
  }
}/* ===== GSM HASAN PREMIUM CATEGORY REDESIGN ===== */

/* MAIN OUTER PANEL */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] {
  background: linear-gradient(135deg,#020817,#0a2040,#031225) !important;
  border: 1px solid #087fc7 !important;
  border-radius: 22px !important;
  padding: 25px 16px !important;
  box-shadow: 0 0 30px rgba(0,160,255,.25) !important;
}

/* GSM HASAN TITLE */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] h2 {
  color: #19dcff !important;
  font-size: 30px !important;
  font-weight: 900 !important;
  text-shadow: 0 0 15px #00aaff !important;
  letter-spacing: 2px !important;
}

div[style*="linear-gradient(135deg"][style*="border-radius:16px"] p {
  color: #d9edff !important;
}

/* CATEGORY GRID */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] {
  display: grid !important;
  grid-template-columns: repeat(5,minmax(0,1fr)) !important;
  gap: 13px !important;
}

/* ALL FIVE BOXES */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] > div {
  background: linear-gradient(155deg,#123d70,#07172d) !important;
  border: 1px solid #078fdf !important;
  border-radius: 18px !important;
  padding: 18px 13px !important;
  box-shadow: inset 0 0 20px rgba(0,160,255,.12),
              0 5px 20px rgba(0,0,0,.4) !important;
  transition: all .3s ease !important;
}

/* HOVER EFFECT */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] > div:hover {
  transform: translateY(-6px) !important;
  border-color: #00eaff !important;
  box-shadow: 0 0 24px rgba(0,200,255,.45) !important;
}

/* CATEGORY HEADINGS */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] h3 {
  color: #20ddff !important;
  font-weight: 800 !important;
  font-size: 15px !important;
  line-height: 1.5 !important;
}

/* ALL LINKS */
div[style*="linear-gradient(135deg"][style*="border-radius:16px"] a {
  color: #e0f1ff !important;
  text-decoration: none !important;
  transition: .25s !important;
}

div[style*="linear-gradient(135deg"][style*="border-radius:16px"] a:hover {
  color: #00eaff !important;
  padding-left: 5px !important;
}

/* TABLET */
@media(max-width:1000px) {
  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] {
    grid-template-columns: repeat(3,minmax(0,1fr)) !important;
  }
}

/* MOBILE */
@media(max-width:600px) {
  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] {
    padding: 15px 8px !important;
  }

  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] {
    grid-template-columns: repeat(2,minmax(0,1fr)) !important;
    gap: 9px !important;
  }

  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] > div[style*="display:grid"] > div {
    padding: 12px 8px !important;
  }

  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] h3 {
    font-size: 12px !important;
  }

  div[style*="linear-gradient(135deg"][style*="border-radius:16px"] a {
    font-size: 12px !important;
  }
}/* ===== GSM HASAN CYBER PREMIUM BOXES ===== */

/* MAIN PANEL */
div[style*="linear-gradient(135deg"] {
  background: linear-gradient(135deg,#020817,#061a36,#020b19) !important;
  border: 1px solid #00bfff !important;
  border-radius: 20px !important;
  padding: 25px 16px !important;
  box-shadow: 0 0 25px rgba(0,180,255,.25) !important;
}

/* MAIN TITLE */
div[style*="linear-gradient(135deg"] h2 {
  color: #ffffff !important;
  font-size: 32px !important;
  font-weight: 900 !important;
  text-shadow: 0 0 12px #00cfff,0 0 25px #007bff !important;
  letter-spacing: 2px !important;
}

div[style*="linear-gradient(135deg"] p {
  color: #dcefff !important;
  font-weight: bold !important;
  letter-spacing: 1px !important;
}

/* FIVE COLUMN GRID */
div[style*="display:grid"] {
  grid-template-columns: repeat(5,minmax(0,1fr)) !important;
  gap: 13px !important;
}

/* PREMIUM CARDS */
div[style*="background:#0c2948"] {
  position: relative !important;
  background: linear-gradient(160deg,#064b91,#061a37 65%,#020d20) !important;
  border: 2px solid #08bfff !important;
  border-radius: 19px !important;
  padding: 16px 13px !important;
  min-height: 400px !important;
  box-shadow: 0 0 12px rgba(0,174,255,.35),
              inset 0 0 20px rgba(0,120,255,.12) !important;
  transition: all .3s ease !important;
}

/* HOVER GLOW */
div[style*="background:#0c2948"]:hover {
  transform: translateY(-6px) !important;
  border-color: #00f0ff !important;
  box-shadow: 0 0 25px #008cff !important;
}

/* CATEGORY HEADING */
div[style*="background:#0c2948"] h3 {
  background: linear-gradient(135deg,#020b1c,#101d38) !important;
  color: #ffffff !important;
  text-align: center !important;
  font-size: 15px !important;
  font-weight: 900 !important;
  line-height: 1.5 !important;
  padding: 12px 5px !important;
  border: 1px solid #00cfff !important;
  border-radius: 30px !important;
  box-shadow: 0 0 12px rgba(0,190,255,.3) !important;
  margin: 0 0 17px !important;
}

/* CATEGORY LINKS */
